262	  }
263	  function laserIndex(def, x1, y1) { return def.lasers.findIndex((l) => l.x1 === x1 && l.y1 === y1); }
264	
265	  T.add('levels l1 route: west corridor laser leaves a walkable bottom lane', () => {
